// What a cell needs to work with the language server: where to ask about a
// name, the places an answer lists, and a rename planned as exact edits the
// Edit tool can apply. Pure; shared by the runner, the mod and the tests.

const KEYWORDS = 'function|class|interface|type|enum|struct|trait|def|fn|func|const|let|var|val|record|module|namespace'

const IDENT = /^[A-Za-z_$][\w$]*$/

export const isName = name => typeof name === 'string' && IDENT.test(name)

const escape = name => name.replace(/\$/g, '\\$')

/** The 1-based column of `name` as a whole word on one line, or 0. */
function columnOn(text, name) {
  const m = new RegExp(`(^|[^\\w$])${escape(name)}(?![\\w$])`).exec(text)
  return m ? m.index + m[1].length + 1 : 0
}

/**
 * Where to ask the language server about `name` in a file's text: on `line`
 * when given, else where it is defined, else where it first appears. 1-based.
 */
export function anchorIn(text, name, line = 0) {
  const lines = String(text).split('\n')
  if (line > 0) {
    const col = columnOn(lines[line - 1] ?? '', name)
    return col ? { line, col } : undefined
  }
  const def = new RegExp(`\\b(?:${KEYWORDS})\\s+${escape(name)}(?![\\w$])`)
  const at = lines.findIndex(l => def.test(l))
  const first = at >= 0 ? at : lines.findIndex(l => columnOn(l, name) > 0)
  if (first < 0) return undefined
  return { line: first + 1, col: columnOn(lines[first], name) }
}

/**
 * The places an LSP answer lists, whichever way it lists them: a `path:`
 * heading over `Line l:c` rows (references), or `path:l:c` inline
 * (`Defined in src/a.ts:24:17`). Columns are 0 where the answer gives none.
 */
export function parseLocations(text) {
  const found = []
  let file
  for (const row of String(text).split('\n')) {
    const heading = /^\s*((?:\/|\.{1,2}\/)?[\w@.\-/ ]+\.\w+):\s*$/.exec(row)
    if (heading) {
      file = heading[1].trim()
      continue
    }
    const at = /^\s*(?:[-•*]\s*)?Line\s+(\d+)(?::(\d+))?/i.exec(row)
    if (at && file !== undefined) {
      found.push({ file, line: Number(at[1]), col: Number(at[2] ?? 0) })
      continue
    }
    for (const m of row.matchAll(/((?:\/|\.{1,2}\/)?[\w@.\-/]+\.[A-Za-z]\w*):(\d+)(?::(\d+))?/g)) {
      found.push({ file: m[1], line: Number(m[2]), col: Number(m[3] ?? 0) })
    }
  }
  const seen = new Set()
  return found.filter(p => {
    const key = `${p.file}:${p.line}:${p.col}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
}

/** How often `part` occurs in `text`, matches not overlapping (as the Edit tool counts). */
function occurrences(text, part) {
  let n = 0
  for (let at = text.indexOf(part); at >= 0; at = text.indexOf(part, at + part.length)) n++
  return n
}

/** Context lines an edit may grow by to make its text unique in the file. */
const MAX_CONTEXT = 12

/**
 * A rename in one file's text, as exact edits: every place (1-based line and
 * column where `name` starts) becomes `newName`. Places where the text does
 * not hold `name` as a whole word are skipped and said so. Each edit is a
 * run of whole lines, grown by context until it occurs once in the file as
 * it stands when that edit is applied; edits come bottom to top, the order
 * to apply them in.
 */
export function planRename(text, places, name, newName) {
  const lines = String(text).split('\n')
  const skipped = []
  const cols = new Map()
  for (const { line, col } of places) {
    const l = lines[line - 1]
    const ok =
      l !== undefined &&
      col > 0 &&
      l.slice(col - 1, col - 1 + name.length) === name &&
      !/[\w$]/.test(l[col - 2] ?? '') &&
      !/[\w$]/.test(l[col - 1 + name.length] ?? '')
    if (!ok) {
      skipped.push({ line, col, text: (l ?? '').trim().slice(0, 160) })
      continue
    }
    if (!cols.has(line)) cols.set(line, new Set())
    cols.get(line).add(col)
  }

  const renamed = new Map()
  let changed = 0
  for (const [line, set] of cols) {
    let l = lines[line - 1]
    for (const col of [...set].sort((a, b) => b - a)) {
      l = l.slice(0, col - 1) + newName + l.slice(col - 1 + name.length)
      changed++
    }
    renamed.set(line, l)
  }

  const blocks = []
  for (const n of [...renamed.keys()].sort((a, b) => a - b)) {
    const last = blocks.at(-1)
    if (last && n === last.to + 1) last.to = n
    else blocks.push({ from: n, to: n })
  }

  const current = lines.slice()
  const edits = []
  const ambiguous = []
  for (const { from, to } of blocks.reverse()) {
    let a = from
    let b = to
    const old = () => current.slice(a - 1, b).join('\n')
    let grown = 0
    while (occurrences(current.join('\n'), old()) !== 1 && grown < MAX_CONTEXT) {
      if (grown % 2 === 0 && a > 1) a--
      else if (b < current.length) b++
      else if (a > 1) a--
      else break
      grown++
    }
    if (occurrences(current.join('\n'), old()) !== 1) {
      for (let n = from; n <= to; n++) ambiguous.push({ line: n, text: lines[n - 1].trim().slice(0, 160) })
      continue
    }
    const before = old()
    for (let n = from; n <= to; n++) current[n - 1] = renamed.get(n)
    edits.push({ old: before, new: current.slice(a - 1, b).join('\n') })
  }
  return { edits, changed, skipped, ambiguous }
}

/** `path:line:text` rows of a grep, as places; at most `max`, with the count of all. */
export function parseMentions(out, max = 40) {
  const rows = String(out)
    .split('\n')
    .map(r => /^(.+?):(\d+):(.*)$/.exec(r))
    .filter(Boolean)
  return {
    count: rows.length,
    places: rows.slice(0, max).map(m => ({ file: m[1], line: Number(m[2]), text: m[3].trim().slice(0, 160) })),
  }
}

files.runner/repair.mjs:
// Cells that do not parse: what can be said about them deterministically, and
// a repair for the one slip that has a single reading. Nothing here runs a
// program; the runner checks that a repair parses, and the model decides
// whether to run it. Pure; shared by the runner, the mod and the tests.

/**
 * Where code holds an escape that is only valid inside a template literal
 * (`` \` `` or `\${`) outside of any string, template, comment or regular
 * expression: the sign of code escaped for a template it is not in. -1 if
 * there is none.
 */
export function strayEscapeAt(code) {
  const stack = [] // 'tpl' inside a template's text, 'expr' inside its ${…}, 'brace' inside other braces
  let prev = '' // the last significant character, to tell a regular expression from a division
  let i = 0
  while (i < code.length) {
    const c = code[i]
    const n = code[i + 1]
    if (stack.at(-1) === 'tpl') {
      if (c === '\\') i += 2
      else if (c === '`') {
        stack.pop()
        prev = '`'
        i++
      } else if (c === '$' && n === '{') {
        stack.push('expr')
        i += 2
      } else i++
      continue
    }
    if (c === '\\' && (n === '`' || (n === '$' && code[i + 2] === '{'))) return i
    if (c === '/' && n === '/') {
      const end = code.indexOf('\n', i)
      i = end < 0 ? code.length : end
      continue
    }
    if (c === '/' && n === '*') {
      const end = code.indexOf('*/', i + 2)
      i = end < 0 ? code.length : end + 2
      continue
    }
    if (c === '"' || c === "'") {
      i++
      while (i < code.length && code[i] !== c && code[i] !== '\n') i += code[i] === '\\' ? 2 : 1
      i++
      prev = 'a'
      continue
    }
    if (c === '/' && !/[\w$)\]}`'"]/.test(prev)) {
      // A regular expression: up to the closing slash outside a class, then its flags.
      let inClass = false
      i++
      while (i < code.length && code[i] !== '\n') {
        if (code[i] === '\\') i += 2
        else if (code[i] === '[') (inClass = true), i++
        else if (code[i] === ']') (inClass = false), i++
        else if (code[i] === '/' && !inClass) break
        else i++
      }
      i++
      while (/[a-z]/.test(code[i] ?? '')) i++
      prev = 'a'
      continue
    }
    if (c === '`') stack.push('tpl')
    else if (c === '{') stack.push('brace')
    else if (c === '}') stack.pop()
    if (!/\s/.test(c)) prev = c
    i++
  }
  return -1
}

/** Escapes that mean the same written once as written twice: kept as escapes, so no line moves. */
const KEPT = new Set(['n', 'r', 't', 'b', 'f', 'v', '0', 'u', 'x'])

/**
 * A template literal written as if inside another one, read the way that
 * outer template would have read it: from the stray `` \` `` at `start` to its
 * closing `` \` ``, one level of escaping comes off (`` \` `` → `` ` ``,
 * `\${` → `${`, `\\` → `\`); `\n` and its kind stay escapes, so no line moves.
 * Undefined when it never closes.
 */
function unescapeRegion(code, start) {
  let out = '`'
  let escaped = false // the last character of the read text was a lone backslash
  let i = start + 2
  while (i < code.length) {
    let ch
    if (code[i] === '\\' && i + 1 < code.length) {
      const next = code[i + 1]
      i += 2
      if (KEPT.has(next)) {
        out += `\\${next}`
        escaped = false
        continue
      }
      ch = next
    } else {
      ch = code[i]
      i++
    }
    if (ch === '`' && !escaped) return { text: `${out}\``, end: i }
    out += ch
    escaped = ch === '\\' && !escaped
  }
  return undefined
}

/**
 * Every template the code escaped as if it sat inside another one, with one
 * level of escaping taken off; the 1-based lines each began on. Undefined
 * when there is none, or one that never closes.
 */
export function unescapeTemplates(code) {
  let text = code
  const lines = []
  for (let round = 0; round < 20; round++) {
    const at = strayEscapeAt(text)
    if (at < 0) break
    if (text[at + 1] !== '`') return undefined
    const region = unescapeRegion(text, at)
    if (region === undefined) return undefined
    lines.push(text.slice(0, at).split('\n').length)
    text = text.slice(0, at) + region.text + text.slice(region.end)
  }
  return lines.length > 0 ? { code: text, lines } : undefined
}

/** Exact replacements in a program, each of whose old text occurs once, as the Edit tool takes them. */
export function applyFixes(code, fixes) {
  let text = code
  for (const [k, f] of fixes.entries()) {
    const old = String(f?.old ?? '')
    const count = old === '' ? 0 : text.split(old).length - 1
    if (count !== 1) return { error: `fix ${k + 1}: its old text occurs ${count} times in the program; it must occur once` }
    text = text.replace(old, () => String(f.new ?? ''))
  }
  return { code: text }
}

/** Where a program failed to parse, as the model reads it: the message, the line and a caret. */
export function describeSyntax(message, code, line, caret) {
  const shown = line !== undefined ? code.split('\n')[line - 1] : undefined
  const at = line !== undefined ? ` (line ${line})` : ''
  const frame = shown === undefined ? '' : `\n  ${shown.length > 200 ? `${shown.slice(0, 199)}…` : shown}${caret ? `\n  ${caret}` : ''}`
  return `SyntaxError: ${message}${at}; nothing ran.${frame}`
}

files.hooks/bridge.ts:
// Runs one cell: starts the sandboxed runner, serves each tool call it asks
// for through Claude Code's own tools, and writes the result the model reads.

import { cut } from '../runner/fold.mjs'
import type { Place } from '../runner/lsp.mjs'

export type Need = { n: number; tool: string; input: Record<string, unknown> }

/** What the runner reads back for one call. */
export type Reply = {
  ok: boolean
  denied?: string
  text?: string
  out?: string
  err?: string
  code?: number
  content?: string
  /** Read: where the page starts, how many lines it holds, how many the file has. */
  start?: number
  num?: number
  total?: number
  /** Bash in the background: the task's id and the file its output goes to. */
  task?: string
  file?: string
  /** LSP: the places the answer lists, and what a plugin above added. */
  places?: Place[]
  context?: string[]
}

export type Done = {
  output: string
  log: string
  previews: string
  handles: string
  dropped: string[]
  error?: string
  /** The program did not parse, so nothing ran. */
  unparsed?: boolean
  /** That program with one level of escaping taken off templates written as if inside another one, where that parses; the lines they began on, and what changed. */
  repaired?: string
  repairedLines?: number[]
  repairPreview?: string
}

export type CallRecord = { tool: string; label: string; ok: boolean; refused: boolean; ms: number; note?: string }

export const MARK = '\u0001cell '
export const MAX_IN_FLIGHT = 4

const VERB: Record<string, string> = { Bash: 'sh', Read: 'read', Edit: 'edit', Write: 'write', LSP: 'lsp' }

export function labelOf(need: Need): string {
  const i = need.input
  if (need.tool === 'Bash') return String(i.command ?? '').replace(/\s+/g, ' ').trim()
  if (need.tool === 'LSP') return `${String(i.operation ?? '')} ${String(i.filePath ?? '')}:${String(i.line ?? '')}:${String(i.character ?? '')}`
  return String(i.file_path ?? '')
}

export function absolute(cwd: string, file: unknown): string {
  const p = String(file ?? '')
  return p.startsWith('/') ? p : `${cwd.replace(/\/$/, '')}/${p.replace(/^\.\//, '')}`
}

/** A path as a cell should see it: relative to `cwd` when inside it, else absolute; `.` and `..` resolved. */
export function tidy(cwd: string, file: string): string {
  const parts: string[] = []
  for (const part of absolute(cwd, file).split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') parts.pop()
    else parts.push(part)
  }
  const full = `/${parts.join('/')}`
  const root = cwd.replace(/\/$/, '')
  return full.startsWith(`${root}/`) ? full.slice(root.length + 1) : full
}

/** The exit code Claude Code writes at the head of a failed Bash result. */
export function exitCode(text: string | undefined): number {
  const m = /^Exit code (\d+)/m.exec(text ?? '')
  return m ? Number(m[1]) : 1
}

/** Splits the runner's stdout into its messages, keeping a partial line. */
export function lines(buffer: string): { messages: unknown[]; rest: string } {
  const messages: unknown[] = []
  let rest = buffer
  let at = rest.indexOf('\n')
  while (at >= 0) {
    const line = rest.slice(0, at)
    rest = rest.slice(at + 1)
    if (line.startsWith(MARK)) {
      try {
        messages.push(JSON.parse(line.slice(MARK.length)))
      } catch {
        // A line the runner did not write whole; nothing to act on.
      }
    }
    at = rest.indexOf('\n')
  }
  return { messages, rest }
}

function seconds(ms: number): string {
  return ms < 10_000 ? `${(ms / 1000).toFixed(1)} s` : `${Math.round(ms / 1000)} s`
}

/** The one tool result the model reads for a cell. */
/** Notes from other plugins a report carries at most, each cut to NOTE_ROOM. */
const MAX_NOTES = 6
const NOTE_ROOM = 800

export function report(calls: readonly CallRecord[], done: Done | undefined, ms: number, stderr: string, notes: readonly string[] = []): string {
  const failed = calls.filter(c => !c.ok).length
  const head = `cell · ${calls.length} call${calls.length === 1 ? '' : 's'}${failed ? ` · ${failed} failed` : ''} · ${seconds(ms)}`
  const rows = calls.map(c => {
    const mark = c.refused ? '⊘' : c.ok ? '✓' : '✕'
    const verb = (VERB[c.tool] ?? c.tool).padEnd(5)
    const label = c.label.length > 90 ? `${c.label.slice(0, 89)}…` : c.label
    const note = c.note ? `  ${c.note}` : ''
    return `  ${mark} ${verb} ${label}${note}  ${seconds(c.ms)}`
  })
  const parts = [head, ...rows]

  if (!done) {
    parts.push('## Error', `the runner ended without a result${stderr ? `:\n${cut(stderr, 1500)}` : ''}`)
    return parts.join('\n')
  }
  if (done.output) parts.push('## Output', done.output)
  if (done.log) parts.push('## Log', done.log)
  if (done.previews) parts.push('## Handles', done.previews)
  if (done.dropped.length > 0) parts.push(`(not kept, too large: ${done.dropped.map(k => `h.${k}`).join(', ')})`)
  if (notes.length > 0) {
    parts.push('## Notes', ...notes.slice(0, MAX_NOTES).map(n => cut(n, NOTE_ROOM)))
    if (notes.length > MAX_NOTES) parts.push(`(${notes.length - MAX_NOTES} more notes not shown)`)
  }
  if (done.error) parts.push('## Error', done.error)
  if (done.unparsed && done.repaired !== undefined) {
    const lines = done.repairedLines ?? []
    parts.push(
      '## Repair',
      'Line' + (lines.length === 1 ? ' ' : 's ') + lines.join(', ') + ': a template literal escaped as if it sat inside another one (\\` or \\${ outside any template). With one level of escaping taken off, the program parses:',
      done.repairPreview ?? '',
      'Run it so with run_cell({ repair: true }), or fix it with run_cell({ fix: [{ old, new }] }).',
    )
  } else if (done.unparsed || (done.error !== undefined && calls.length === 0)) {
    parts.push('## Fix', 'Send run_cell({ fix: [{ old, new }] }): exact replacements in this program, which then runs. No need to send it again.')
  }
  if (!done.output && !done.log && !done.error && calls.length > 0) parts.push('(the cell returned nothing)')
  return parts.join('\n')
}

files.hooks/isolation.ts:
// Where a cell's runner may run, and how it is shut in.
//
// What a cell does to the machine it does through Claude Code's tools, which the person's
// permissions and auto mode judge one call at a time. The runner itself must have no other
// way out, or one run_cell call could do what no tool call shows. Node's permission model
// closes the disk, child processes and workers, and from Node 25 on the network; an OS
// sandbox closes the network and signals on any Node: Seatbelt on macOS, bubblewrap on Linux.
// Where nothing closes the network, cells does not run, and says what would let it.

/** What the `node` on Claude Code's PATH reports about itself. */
export type Probe = { nodePath: string; platform: string; nodeVersion: string; tmpdir: string }

export type Sandbox = 'seatbelt' | 'bwrap' | 'node'

export type Isolation =
  | { sandbox: Sandbox; signalsOpen: boolean }
  | { sandbox: undefined; why: string; fix: string }

/** From Node 25 the permission model also refuses network access unless `--allow-net` opens it. */
export const NODE_NET_MAJOR = 25

/** The major version of "26.1.0" or "v22.22.3"; 0 when it is not a version. */
export function major(version: string): number {
  return Number(/^v?(\d+)\./.exec(version)?.[1] ?? 0)
}

/** The program `node -p` runs to report its path, platform and version as JSON. */
export const PROBE_SCRIPT = 'JSON.stringify([process.execPath, process.platform, process.versions.node, require("os").tmpdir()])'

export function parseProbe(stdout: string): Probe | undefined {
  try {
    const [nodePath, platform, nodeVersion, tmpdir] = JSON.parse(stdout) as unknown[]
    if (typeof nodePath !== 'string' || typeof platform !== 'string' || typeof nodeVersion !== 'string' || typeof tmpdir !== 'string') return undefined
    return { nodePath, platform, nodeVersion, tmpdir }
  } catch {
    return undefined
  }
}

/** bubblewrap's verdict: whether it started a program in the sandbox, and if not, its first word on why. */
export type Bwrap = { works: boolean; why?: string }

export function choose(probe: Probe, bwrap: Bwrap): Isolation {
  if (probe.platform === 'darwin') return { sandbox: 'seatbelt', signalsOpen: false }
  if (probe.platform === 'linux' && bwrap.works) return { sandbox: 'bwrap', signalsOpen: false }
  if (major(probe.nodeVersion) >= NODE_NET_MAJOR) return { sandbox: 'node', signalsOpen: true }
  const node = `Node ${probe.nodeVersion} lets a program reach the network`
  if (probe.platform === 'linux') {
    const sandbox = bwrap.why ? `bubblewrap can't start a sandbox here (${bwrap.why})` : 'bubblewrap (bwrap) is not installed'
    return { sandbox: undefined, why: `${sandbox}, and ${node}`, fix: 'install Node 25 or later, or make bubblewrap work' }
  }
  return { sandbox: undefined, why: `there is no OS sandbox for it here, and ${node}`, fix: 'install Node 25 or later' }
}

/** The runner under Node's permission model: it reads its own folder and the cell's, nothing else. */
export function nodeArgv(nodePath: string, runner: string, dir: string): string[] {
  return [nodePath, '--permission', `--allow-fs-read=${runner}`, `--allow-fs-read=${dir}`, '--no-warnings', `${runner}/runner.mjs`]
}

export function seatbeltArgv(nodePath: string, runner: string, dir: string): string[] {
  return ['/usr/bin/sandbox-exec', '-f', `${runner}/profile.sb`, ...nodeArgv(nodePath, runner, dir)]
}

/**
 * bubblewrap: every namespace its own (network, processes, IPC), so neither the network nor
 * another process is in reach; read-only binds of the system's libraries, Node, the runner
 * and the cell's folder, and nothing else of the host's files. Assumes a merged /usr, as
 * Debian, Ubuntu, Fedora and Arch have it.
 */
export function bwrapArgv(nodePath: string, runner: string, dir: string, program: string[] = nodeArgv(nodePath, runner, dir)): string[] {
  // Node's install prefix: /usr/local/bin/node → /usr/local, ~/.nvm/versions/node/v25.1.0/bin/node → its version folder.
  const prefix = nodePath.replace(/\/bin\/[^/]+$/, '')
  const nodeBind = prefix === '/usr' || prefix.startsWith('/usr/') ? [] : ['--ro-bind', prefix, prefix]
  return [
    'bwrap', '--unshare-all', '--die-with-parent', '--new-session', '--cap-drop', 'ALL', '--clearenv',
    '--ro-bind', '/usr', '/usr', '--symlink', 'usr/lib', '/lib', '--symlink', 'usr/lib64', '/lib64', '--symlink', 'usr/bin', '/bin',
    '--ro-bind-try', '/etc/ld.so.cache', '/etc/ld.so.cache',
    ...nodeBind,
    '--ro-bind', runner, runner,
    '--ro-bind', dir, dir,
    '--dev', '/dev',
    ...program,
  ]
}

export function runnerArgv(isolation: Isolation, nodePath: string, runner: string, dir: string): string[] | undefined {
  if (isolation.sandbox === 'seatbelt') return seatbeltArgv(nodePath, runner, dir)
  if (isolation.sandbox === 'bwrap') return bwrapArgv(nodePath, runner, dir)
  if (isolation.sandbox === 'node') return nodeArgv(nodePath, runner, dir)
  return undefined
}

/** What a cell's report adds to its first line where the runner is shut in less than elsewhere. */
export function weakness(isolation: Isolation): string | undefined {
  return isolation.sandbox === 'node' && isolation.signalsOpen ? "Node's sandbox only: signals open" : undefined
}

/** The system-prompt section where cells cannot run: Claude offers the fix once, the person decides. */
export function offNote(why: string, fix: string): string {
  return `# cells is off on this machine

The cells mod could not start its run_cell tool: ${why}. Where chaining several edits and their check in one step would have helped the person, tell them once and offer the fix (${fix}); /cells:setup walks them through it. Don't bring it up again after that.`
}

/** The line the person sees where cells cannot run. */
export function offLine(why: string, fix: string): string {
  return `cells is off: ${why}. To turn it on, ${fix}, or run /cells:setup.`
}

files.hooks/nudge.ts:
// Notes after the fact: when a model request did no more than a step that
// needed no judgment (a check right after edits, one more single edit, the
// same command again), its tool result says what that request re-read and
// how to save it next time; a script that rewrote files around the Edit tool
// is pointed to run_cell. Notes only, never a block, and few of them.

export type Kind = 'edit' | 'script-edit' | 'check' | 'edit-check' | 'bash' | 'other'

/** A command that tests, type-checks, builds or lints. */
const CHECK =
  /(\btsc\b|pytest|py\.test|\bnpm (run )?(test|build|lint|check|typecheck)\b|\b(pnpm|yarn|bun) (run )?(test|build|lint|typecheck)\b|\bcargo (test|check|build|clippy)\b|\bgo (test|build|vet)\b|claude plugin (test|validate)|\bruff\b|\bmypy\b|\bpyright\b|\beslint\b|\bjest\b|\bvitest\b|(^|[;&|]\s*)make\b|\bswift (build|test)\b|xcodebuild|\bgradle\b|\bmvn\b|dotnet (build|test)|node --test|-m (pytest|unittest)\b|board validate|latexmk|\bshellcheck\b|py_compile|node --check)/

/** A command that writes files: a script, sed or perl in place, a redirect into a file. */
const WRITES = /(\.write\(|open\([^)]*['"][wa]['"]|write_text\(|writeFileSync|\bsed -i|\bperl -[a-z0-9]*i|\bcat >|\btee \S)/

/**
 * A script that rewrites text inside existing files: Python or Node replacing
 * and writing back, or perl in place. Exact and multi-line replacements are
 * what the Edit tool is for; a one-line `sed -i` or a new file is not meant.
 */
const REWRITES = /(\.replace\(|re\.sub\(|\.sub\(|splice|\.slice\()[\s\S]*(open\([^)]*['"]w['"]|write_text\(|writeFileSync)|\bperl -[a-z0-9]*pi/

export function kindOf(tool: string, input: unknown): Kind {
  if (tool === 'Edit' || tool === 'Write' || tool === 'MultiEdit' || tool === 'NotebookEdit') return 'edit'
  if (tool !== 'Bash') return 'other'
  const command = String((input as { command?: unknown } | undefined)?.command ?? '')
  const writes = WRITES.test(command)
  const checks = CHECK.test(command)
  if (writes && checks) return 'edit-check'
  if (writes) return 'script-edit'
  if (checks) return 'check'
  return 'bash'
}

export function rewritesText(command: string): boolean {
  return REWRITES.test(command)
}

/** One model request of the main loop, as far as the notes need it. */
export type Step = {
  turnId: string
  index: number
  calls: { tool: string; kind: Kind; command?: string }[]
  /** Whether each call has come back without an error, in the order they did. */
  ok: boolean[]
  /** Tokens the request read: from the cache, and uncached. */
  readTokens: number
  uncachedTokens: number
  model: string
  ms: number
}

export type Pattern = 'check-alone' | 'edit-alone' | 'repeat' | 'script-edit'

const normal = (command: string | undefined) => (command ?? '').replace(/\s+/g, ' ').trim()

/**
 * Which avoidable step `current` was, given the request before it in the same
 * turn, as seen from `mine`, one of its calls; undefined when it was none.
 */
export function missed(previous: Step | undefined, current: Step, mine: Step['calls'][number], cells: boolean): Pattern | undefined {
  if (cells && mine.kind === 'script-edit' && rewritesText(mine.command ?? '')) return 'script-edit'
  const before =
    previous !== undefined && previous.turnId === current.turnId && previous.index === current.index - 1 && previous.calls.length > 0
      ? previous
      : undefined
  if (before === undefined || current.calls.length !== 1) return undefined
  const fine = before.ok.length === before.calls.length && before.ok.every(Boolean)
  if (mine.kind === 'check' && fine && before.calls.every(c => c.kind === 'edit' || c.kind === 'script-edit')) return 'check-alone'
  if (mine.kind === 'edit' && fine && before.calls.length === 1 && before.calls[0]?.kind === 'edit') return 'edit-alone'
  const only = before.calls.length === 1 ? before.calls[0] : undefined
  if (only !== undefined && (only.kind === 'bash' || only.kind === 'check') && (mine.kind === 'bash' || mine.kind === 'check')) {
    const a = normal(only.command)
    const b = normal(mine.command)
    if (a !== '' && (a === b || (/\bsleep \d/.test(a) && /\bsleep \d/.test(b)))) return 'repeat'
  }
  return undefined
}

/** How often each note may come: the first in full, later ones short, spaced out and capped. */
const LIMITS: Record<Pattern, { gap: number; max: number }> = {
  'check-alone': { gap: 12, max: 4 },
  'edit-alone': { gap: 12, max: 4 },
  repeat: { gap: 8, max: 4 },
  'script-edit': { gap: 25, max: 3 },
}

export class Budget {
  private fired = new Map<Pattern, { count: number; step: number }>()

  /** 'full' the first time, 'short' when a later note is due, else undefined. Counts what it allows. */
  take(pattern: Pattern, step: number): 'full' | 'short' | undefined {
    const seen = this.fired.get(pattern)
    const limit = LIMITS[pattern]
    if (seen === undefined) {
      this.fired.set(pattern, { count: 1, step })
      return 'full'
    }
    if (seen.count >= limit.max || step - seen.step < limit.gap) return undefined
    this.fired.set(pattern, { count: seen.count + 1, step })
    return 'short'
  }
}

/** $/M tokens, list prices, as Claude Code totals them. */
const PRICES: Record<string, { read: number; input: number }> = {
  haiku: { read: 0.01, input: 0.1 },
  sonnet: { read: 0.2, input: 2 },
  opus: { read: 0.2, input: 4 },
  fable: { read: 0.25, input: 10 },
}

/** What re-reading the context cost the request: "412k tokens, ≈$0.08, 6 s". */
export function costOf(step: Step): string {
  const key = Object.keys(PRICES).find(k => step.model.toLowerCase().includes(k)) ?? 'opus'
  const p = PRICES[key] as { read: number; input: number }
  const usd = (step.readTokens * p.read + step.uncachedTokens * p.input) / 1e6
  const tokens = step.readTokens + step.uncachedTokens
  const k = tokens >= 1000 ? `${Math.round(tokens / 1000)}k` : String(tokens)
  const money = usd < 0.01 ? `≈$${usd.toFixed(3)}` : `≈$${usd.toFixed(2)}`
  return `${k} tokens, ${money}, ${Math.max(1, Math.round(step.ms / 1000))} s`
}

export function noteFor(pattern: Pattern, size: 'full' | 'short', cost: string, cells: boolean): string {
  if (pattern === 'check-alone') {
    return size === 'full'
      ? `cells: this check ran in a model request of its own right after the edits, and that request re-read the whole context (${cost}). Next time send the check in the same response as the edits: calls in one response run in order, so it sees them.${cells ? ' Or make the edits and the check one run_cell that returns only what failed.' : ''}`
      : `cells: another check in a request of its own (${cost}); it can go in the response with the edits.`
  }
  if (pattern === 'edit-alone') {
    return size === 'full'
      ? `cells: a second request in a row that made one edit; it re-read the whole context (${cost}). Edits you already know can go together in one response${cells ? ', or into one run_cell with their check' : ''}.`
      : `cells: another one-edit request (${cost}); edits you already know can go together.`
  }
  if (pattern === 'repeat') {
    return size === 'full'
      ? `cells: the same command again in a new request (${cost}). To wait for something, wait in one command (\`until <test>; do sleep 5; done\`) or watch it with Monitor.`
      : `cells: the same command again (${cost}); wait in one command instead.`
  }
  return size === 'full'
    ? 'cells: this script rewrote files around the Edit tool, so the person sees no diff and checkpoints do not track it (/rewind cannot restore it). run_cell does the same in one step through Edit: `await read(p); await edit(p, old, new); return (await sh(check)).out`, and rename(path, name, newName) renames a symbol by its references.'
    : "cells: another script edit around the Edit tool; run_cell's edit() keeps the diff and /rewind."
}

files.hooks/subagents.ts:
// A subagent Claude starts has a system prompt of its own, which the chaining guidance (a section of the main one)
// never reaches; the task it is given is the one thing that rides with it. Pure: no I/O.
//
// Measured in the person's transcripts: 0 of 18 subagents had the guidance, and general-purpose subagents ran about a
// third of the person's Opus requests, most of the longer ones without run_cell. An order beside the task, in the
// person's name, is followed; advice is not.

/**
 * The block the pack's mods put their settings under, at the end of a subagent's task; each mod adds its own line,
 * so either can be turned off alone. seek writes the same head.
 */
export const SETTINGS_HEAD = "The person's settings for this work:"

/** The task with one more setting: a line under the block a mod before this one began, or a new block at the end. */
export function withSetting(prompt: string, line: string): string {
  if (prompt.includes(line)) return prompt
  const at = prompt.lastIndexOf(`\n\n${SETTINGS_HEAD}\n`)
  if (at >= 0 && !prompt.slice(at + 2).includes('\n\n')) return `${prompt.trimEnd()}\n- ${line}`
  return `${prompt.trimEnd()}\n\n${SETTINGS_HEAD}\n- ${line}`
}

type Spawn = { subagentType: string; fork: boolean; isTeammate?: true; resume?: unknown }

/**
 * Whether a spawn starts a subagent on a task of its own: not a fork (it has the parent's context, the guidance
 * included), not a resume (its task is fixed), not a teammate, not delegate's worker (a tuned prompt, no run_cell).
 */
export function reaches(e: Spawn): boolean {
  return !e.fork && e.resume === undefined && e.isTeammate !== true && !e.subagentType.startsWith('delegate:')
}

/** The chaining guidance, short, for a subagent's task. */
export const SUBAGENT_CHAINING =
  'Fewer round-trips: every response you make re-reads the whole conversation, so a step that needs no judgment should not cost a response of its own. ' +
  'Get what you already know you need in one Bash call (join the commands with `;`, label each part with an `echo`) or as parallel tool calls in one response; ' +
  'send edits you already know in one response with their check after them; when a search names the files you will open next, open them in the same command. ' +
  'Take a separate step only when what you do next depends on reading the result.'

/** Added only where the session has the tool; a subagent whose type lists its own tools may not. */
export const SUBAGENT_CELLS =
  "Where you have the run_cell tool, it chains real tool calls one response can't: edits and their check, the language server's references and renames, steps that follow from each other without your judgment."

files.hooks/view.tsx:
// How a cell draws in the transcript, after sterna's cells: a rounded card
// with the program dimmed, one row per call with its mark and time, and a
// closing line that carries the state. Only what is changing state moves:
// the scanner beside a running cell's state, and a turning disc on the call
// in flight.

import type { BoxProps, ElementConstructor, RenderElement, TextProps } from 'claude-code'

import type { CellsCall, CellsLive } from '../types'

export type Elements = { Box: ElementConstructor<BoxProps>; Text: ElementConstructor<TextProps> }

export type CellState = 'writing' | 'running' | 'background' | 'ran' | 'failed' | 'threw' | 'stopped'

export type Card = {
  state: CellState
  code: string
  calls: readonly CellsCall[]
  now: number
  frame: number
  width: number
  summary: string
}

/** How wide the scanner is, and its two-cell head sweeping out and back. */
const SCAN = 10
const TURN = ['◐', '◓', '◑', '◒'] as const
const VERB: Record<string, string> = { Bash: 'sh', Read: 'read', Edit: 'edit', Write: 'write', LSP: 'lsp' }
const CODE_LINES = 6

export function scanner(frame: number): { before: string; head: string; after: string } {
  const span = SCAN - 2
  const t = frame % (2 * span)
  const at = t <= span ? t : 2 * span - t
  return { before: '·'.repeat(at), head: '━━', after: '·'.repeat(span - at) }
}

/** A cell's state from its own record: running until it has ended, whatever its row says. */
export function stateOf(live: CellsLive, rowRunning: boolean): CellState {
  if (live.stopped) return 'stopped'
  if (rowRunning || live.endedAt === undefined) return live.background ? 'background' : 'running'
  if (live.error) return 'threw'
  return live.calls.some(c => c.state !== 'ok' && c.state !== 'running') ? 'failed' : 'ran'
}

export function seconds(ms: number): string {
  return ms < 10_000 ? `${(Math.max(0, ms) / 1000).toFixed(1)} s` : `${Math.round(ms / 1000)} s`
}

function fit(text: string, room: number): string {
  const flat = text.replace(/\s+/g, ' ').trim()
  return flat.length > room ? `${flat.slice(0, Math.max(1, room - 1))}…` : flat
}

const TONE: Record<CellState, string> = { writing: 'claude', running: 'claude', background: 'claude', ran: 'success', failed: 'warning', threw: 'error', stopped: 'warning' }

export function cellCard({ Box, Text }: Elements, c: Card): RenderElement {
  const inner = Math.max(24, c.width - 6)
  const sweep = scanner(c.frame)
  const program = c.code.replace(/\s+$/, '')
  const lines = program === '' ? [] : program.split('\n')
  const moving = c.state === 'running' || c.state === 'writing' || c.state === 'background'
  const shown = lines.slice(0, CODE_LINES)

  const footer = (
    <Box flexDirection="row" gap={1}>
      <Text bold color={TONE[c.state]}>
        {c.state}
      </Text>
      {moving ? (
        <Text>
          <Text color="inactive">{sweep.before}</Text>
          <Text color="claude">{sweep.head}</Text>
          <Text color="inactive">{sweep.after}</Text>
        </Text>
      ) : null}
      {c.summary ? <Text color="subtle">{`· ${c.summary}`}</Text> : null}
    </Box>
  )

  const code = lines.length === 0 ? null : (
    <Box flexDirection="column" paddingLeft={2}>
      {shown.map(line => (
        <Text color="subtle" wrap="truncate-end">
          {line.length > inner ? `${line.slice(0, inner - 1)}…` : line || ' '}
        </Text>
      ))}
      {lines.length > CODE_LINES ? <Text color="inactive">{`… ${lines.length - CODE_LINES} more lines`}</Text> : null}
    </Box>
  )

  const rows = c.calls.map(call => {
    const mark =
      call.state === 'running'
        ? TURN[c.frame % TURN.length]
        : call.state === 'ok'
          ? '✓'
          : call.state === 'refused'
            ? '⊘'
            : '✕'
    const markTone = call.state === 'running' ? 'claude' : call.state === 'ok' ? 'success' : call.state === 'refused' ? 'warning' : 'error'
    const ms = call.state === 'running' ? c.now - call.startedAt : (call.ms ?? 0)
    const note = call.note ? `  ${call.note}` : ''
    return (
      <Box flexDirection="row" justifyContent="space-between">
        <Box flexDirection="row" gap={1} flexShrink={1}>
          <Text color={markTone}>{mark}</Text>
          <Text color="subtle">{(VERB[call.tool] ?? call.tool).padEnd(5)}</Text>
          <Text wrap="truncate-end">{fit(call.label, inner - 16 - note.length)}</Text>
          {note ? <Text color="warning">{note.trim()}</Text> : null}
        </Box>
        <Text color="subtle">{seconds(ms)}</Text>
      </Box>
    )
  })

  return (
    <Box flexDirection="column" borderStyle="round" borderColor={moving ? 'claude' : 'subtle'} paddingX={1}>
      {code}
      {rows.length > 0 ? <Box flexDirection="column">{rows}</Box> : null}
      {footer}
    </Box>
  )
}

/** A finished cell rebuilt from the report the model read: its header and call rows. */
export function parseReport(text: string): { summary: string; calls: CellsCall[]; state: CellState } {
  const all = text.split('\n')
  const summary = (all[0] ?? '').replace(/^cell · /, '')
  const calls: CellsCall[] = []
  for (const line of all.slice(1)) {
    const m = /^ {2}([✓✕⊘]) (\S+)\s+(.*?)\s{2}(?:(refused|exit \d+)\s{2})?([\d.]+) s$/.exec(line)
    if (!m) break
    const verb = m[2] ?? ''
    const tool = Object.entries(VERB).find(([, v]) => v === verb)?.[0] ?? verb
    const state = m[1] === '✓' ? 'ok' : m[1] === '⊘' ? 'refused' : 'failed'
    calls.push({ tool, label: m[3] ?? '', state, startedAt: 0, ms: Number(m[5]) * 1000, note: m[4] })
  }
  const threw = /\n## Error\n/.test(text)
  const failed = calls.some(c => c.state !== 'ok')
  return { summary, calls, state: threw ? 'threw' : failed ? 'failed' : 'ran' }
}

export type LineTone = 'error' | 'warning' | 'success' | undefined

const ERROR_LINE = /\berror\b|\bfail(?:ed|s|ure|ures)?\b|✕|✘|\bTraceback\b|\bpanicked\b|\bexception\b|\bexit [1-9]|^E\s/i
const NOT_ERROR = /\b0 (?:errors?|fail(?:ed|s|ures?)?)\b|\bno errors?\b/i
const WARN_LINE = /\bwarn(?:ing)?s?\b|⚠/i
const PASS_LINE = /✔|✓|\bpass(?:ed|es)?\b|\bok\b|\bsucceeded\b/i

/** What a line of a result says, by its words: an error (and the indented lines under one), a warning, a pass. */
export function toneOf(line: string, previous: LineTone): LineTone {
  if (previous === 'error' && /^\s+\S/.test(line) && !PASS_LINE.test(line)) return 'error'
  if (ERROR_LINE.test(line) && !NOT_ERROR.test(line)) return 'error'
  if (WARN_LINE.test(line)) return 'warning'
  if (PASS_LINE.test(line) || NOT_ERROR.test(line)) return 'success'
  return undefined
}

const LOCATION = /^(\s*)((?:[\w@.~-]+\/)*[\w@.~-]+\.\w+(?:\(\d+,\d+\)|:\d+(?::\d+)?):?)(.*)$/

/** A line that starts with where it is about (`a.ts(3,5):`, `a.py:12:`): that place, and the rest. */
export function splitLocation(line: string): { indent: string; at: string; rest: string } | undefined {
  const m = LOCATION.exec(line)
  return m ? { indent: m[1] ?? '', at: m[2] ?? '', rest: m[3] ?? '' } : undefined
}

const SECTION_TONE: Record<string, string> = { error: 'error', repair: 'warning', fix: 'warning', notes: 'suggestion', handles: 'inactive' }
/** Lines a section may take before the long ones share the rest: what went wrong first. */
const SECTION_CAP: Record<string, number> = { error: 8, repair: 8, fix: 2, notes: 4 }
const PRIORITY = ['error', 'repair', 'fix', 'notes', 'output', 'log', 'handles']

/** The part of the report after the call rows: each section under its heading, its lines coloured by what they say, about `room` lines in all. */
export function resultBody({ Box, Text }: Elements, text: string, room = 14): RenderElement | undefined {
  const all = text.split('\n')
  const start = all.findIndex(l => l.startsWith('## '))
  if (start < 0) return undefined
  const sections: { name: string; lines: string[] }[] = []
  for (const line of all.slice(start)) {
    if (line.startsWith('## ')) sections.push({ name: line.slice(3).toLowerCase(), lines: [] })
    else sections.at(-1)?.lines.push(line)
  }

  // What went wrong is shown first and whole (up to its cap); the rest share what is left, two lines each at least.
  const take = new Map<(typeof sections)[number], number>()
  let left = room
  const order = [...sections].sort((a, b) => (PRIORITY.indexOf(a.name) + 1 || 99) - (PRIORITY.indexOf(b.name) + 1 || 99))
  for (const s of order) {
    const want = Math.min(s.lines.length, SECTION_CAP[s.name] ?? s.lines.length)
    const n = Math.min(s.lines.length, Math.max(Math.min(want, left), 2))
    take.set(s, n)
    left = Math.max(0, left - n)
  }

  const row = (line: string, tone: LineTone) => {
    if (line.startsWith('### ')) {
      return (
        <Text bold color="claude">
          {line.slice(4)}
        </Text>
      )
    }
    const place = splitLocation(line)
    if (place === undefined) {
      return (
        <Text wrap="truncate-end" color={tone}>
          {line || ' '}
        </Text>
      )
    }
    return (
      <Text wrap="truncate-end">
        {place.indent}
        <Text color="suggestion">{place.at}</Text>
        <Text color={tone}>{place.rest}</Text>
      </Text>
    )
  }

  return (
    <Box flexDirection="column" paddingLeft={2}>
      {sections.map(s => {
        // A value returned as named parts (\`### tsc\`, \`### tests\`) shows every part, each with its share of the lines.
        const parts = partsOf(s.lines)
        const takes = share(parts, take.get(s) ?? 0)
        return (
          <Box flexDirection="column">
            <Text bold color={SECTION_TONE[s.name] ?? 'subtle'}>
              {s.name}
            </Text>
            <Box flexDirection="column" paddingLeft={1}>
              {parts.map((p, k) => {
                const n = takes[k] ?? 0
                let tone: LineTone
                return (
                  <Box flexDirection="column">
                    {p.head !== undefined ? (
                      <Text bold color="claude">
                        {p.head}
                      </Text>
                    ) : null}
                    {p.lines.slice(0, n).map(line => {
                      tone = s.name === 'handles' ? undefined : toneOf(line, tone)
                      return row(line, s.name === 'error' ? 'error' : tone)
                    })}
                    {p.lines.length > n ? <Text color="inactive">{`… ${p.lines.length - n} more lines (ctrl+o)`}</Text> : null}
                  </Box>
                )
              })}
            </Box>
          </Box>
        )
      })}
    </Box>
  )
}

/** A section's lines split at its \`### name\` headings. */
function partsOf(lines: readonly string[]): { head?: string; lines: string[] }[] {
  const parts: { head?: string; lines: string[] }[] = [{ lines: [] }]
  for (const line of lines) {
    if (line.startsWith('### ')) parts.push({ head: line.slice(4), lines: [] })
    else parts.at(-1)?.lines.push(line)
  }
  return parts.filter(p => p.head !== undefined || p.lines.length > 0)
}

/** `n` lines shared among the parts: two each at least, the rest in order. */
function share(parts: readonly { lines: readonly string[] }[], n: number): number[] {
  const takes = parts.map(p => Math.min(p.lines.length, 2))
  let left = Math.max(0, n - takes.reduce((a, b) => a + b, 0))
  for (let k = 0; k < parts.length && left > 0; k++) {
    const more = Math.min((parts[k]?.lines.length ?? 0) - (takes[k] ?? 0), left)
    takes[k] = (takes[k] ?? 0) + more
    left -= more
  }
  return takes
}

